// 良い例: typeを使用した基本的な型定義
type User = {
  id: string;
  name: string;
  email: string;
  age?: number;
};

// 良い例: Union型を使用
type Status = 'pending' | 'approved' | 'rejected';

// 良い例: Intersection型を使用
type AdminUser = User & {
  role: 'admin';
  permissions: string[];
};

// 良い例: Mapped Typeを使用
type ReadonlyUser = Readonly<User>;

// 良い例: Conditional Typeを使用
type IsString<T> = T extends string ? true : false;

// 悪い例: interfaceを使用（禁止）
interface User {
  id: string;
  name: string;
  email: string;
  age?: number;
}

// 悪い例: interfaceで継承（禁止）
interface AdminUser extends User {
  role: 'admin';
  permissions: string[];
}

// ⚠️ プロジェクトでは上記のようなinterfaceは使用せず、すべてtypeで定義する

// 良い例: Reactコンポーネントのpropsをtypeで定義
type UserCardProps = {
  user: User;
  onEdit?: (userId: string) => void;
  className?: string;
};

export default function UserCard({ user, onEdit, className }: UserCardProps) {
  // ...
}

// 良い例: Server Actionsの引数と戻り値をtypeで定義
type CreateUserInput = {
  name: string;
  email: string;
};

type CreateUserResult = Result<User>;

export async function createUser(input: CreateUserInput): Promise<CreateUserResult> {
  // ...
}

// 良い例: Result型をtypeで定義
type SuccessResult<T> = {
  isSuccess: true;
  data: T;
};

type ErrorResult = {
  isSuccess: false;
  errorMessage: string;
};

export type Result<S> = SuccessResult<S> | ErrorResult;

// 使用例
type FetchUserResult = Result<User>;

const result: FetchUserResult = await fetchUser(userId);
if (result.isSuccess) {
  console.log(result.data.name);
} else {
  console.error(result.errorMessage);
}
